24	/// Layout the cell into the given regions.
25	///
26	/// The `disambiguator` indicates which instance of this cell this should be
27	/// layouted as. For normal cells, it is always `0`, but for headers and
28	/// footers, it indicates the index of the header/footer among all. See the
29	/// [`Locator`] docs for more details on the concepts behind this.
30	pub fn layout_cell(
31	    cell: &Cell,
32	    engine: &mut Engine,
33	    locator: Locator,
34	    styles: StyleChain,
35	    regions: Regions,
36	    is_repeated: bool,
37	) -> SourceResult<Fragment> {
38	    // HACK: manually generate tags for table and grid cells. Ideally table and
39	    // grid cells could just be marked as locatable, but the tags are somehow
40	    // considered significant for layouting. This hack together with a check in
41	    // the grid layouter makes the test suite pass.
42	    let mut locator = locator.split();
43	    let mut tags = None;
44	    if let Some(table_cell) = cell.body.to_packed::<TableCell>() {
45	        let mut table_cell = table_cell.clone();
46	        table_cell.is_repeated.set(is_repeated);
47	        tags = Some(generate_tags(table_cell, &mut locator, engine));
48	    } else if let Some(grid_cell) = cell.body.to_packed::<GridCell>() {
49	        let mut grid_cell = grid_cell.clone();
50	        grid_cell.is_repeated.set(is_repeated);
51	        tags = Some(generate_tags(grid_cell, &mut locator, engine));
52	    }
53	
54	    let locator = locator.next(&cell.body.span());
55	    let fragment = crate::layout_fragment(engine, &cell.body, locator, styles, regions)?;
56	
57	    // Manually insert tags.
58	    let mut frames = fragment.into_frames();
59	    if let Some((elem, loc, key)) = tags
60	        && let Some((first, remainder)) = frames.split_first_mut()
61	    {
62	        let flags = TagFlags { introspectable: true, tagged: true };
63	        if remainder.is_empty() {
64	            first.prepend(Point::zero(), FrameItem::Tag(Tag::Start(elem, flags)));
65	            first.push(Point::zero(), FrameItem::Tag(Tag::End(loc, key, flags)));
66	        } else {
67	            // If there is more than one frame, set the logical parent of all
68	            // frames to the cell, which converts them to group frames. Then
69	            // prepend the start and end tags containing no content. The first
70	            // frame is also a logical child to guarantee correct ordering
71	            // in the introspector, since logical children are currently
72	            // inserted immediately after the start tag of the parent element
73	            // preceding any content within the parent element's tags.
74	            for frame in &mut frames {
75	                frame.set_parent(FrameParent::new(loc, Inherit::Yes));
76	            }
77	            frames.first_mut().unwrap().prepend_multiple([
78	                (Point::zero(), FrameItem::Tag(Tag::Start(elem, flags))),
79	                (Point::zero(), FrameItem::Tag(Tag::End(loc, key, flags))),
80	            ]);
81	        }
82	    }
83	
84	    Ok(Fragment::frames(frames))
85	}
86	
87	fn generate_tags<T: NativeElement>(
88	    mut cell: Packed<T>,
89	    locator: &mut SplitLocator,
90	    engine: &mut Engine,
91	) -> (Content, Location, u128) {
92	    let key = typst_utils::hash128(&cell);
93	    let loc = locator.next_location(engine, key, cell.span());
94	    cell.set_location(loc);
95	    (cell.pack(), loc, key)
96	}
